 public static void Apply(){if(Application.isPlaying)throw new InvalidOperationException("Stop Play first");var g=UnityEngine.Object.FindFirstObjectByType<RangoliGame>();if(g.preserveAuthoredLayout)throw new InvalidOperationException("Authored layout already imported");var old=GameObjectUtility.FindExact("Rangoli - Approved Warm Palette");var oldBoard=GameObjectUtility.FindUnder(old,"Cube.005");var localPoints=g.sockets.Select(z=>oldBoard.InverseTransformPoint(z.transform.position)).ToArray();var localRotations=g.sockets.Select(z=>Quaternion.Inverse(oldBoard.rotation)*z.transform.rotation).ToArray();var oldPieces=g.pieces;var oldDecor=g.decorations;var oldSun=g.sun;var oldZones=g.sockets;
 if(!AssetDatabase.IsValidFolder(Dir+"Materials"))AssetDatabase.CreateFolder(Dir.TrimEnd('/'),"Materials");var data=JObject.Parse(File.ReadAllText(Dir+"manifest.json"));var imported=new System.Collections.Generic.Dictionary<string,Material>();var textures=new System.Collections.Generic.HashSet<string>();
 foreach(var row in data["materials"]){string name=(string)row["name"];string mp=Dir+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,mp);}foreach(var pair in new[]{new[]{"baseColor","_BaseMap"},new[]{"normal","_BumpMap"},new[]{"metallicSmoothness","_MetallicGlossMap"}}){string path=Dir+(string)row[pair[0]];if(textures.Add(path)){var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.textureType=pair[0]=="normal"?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=pair[0]=="baseColor";ti.SaveAndReimport();}m.SetTexture(pair[1],AssetDatabase.LoadAssetAtPath<Texture2D>(path));}m.SetColor("_BaseColor",Color.white);m.SetFloat("_Metallic",1);m.SetFloat("_Smoothness",1);m.SetFloat("_Cull",0);m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");EditorUtility.SetDirty(m);imported[name]=m;}
 var model=AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"Models/Rangoli_Approved.fbx");var root=((GameObject)PrefabUtility.InstantiatePrefab(model)).transform;Undo.RegisterCreatedObjectUndo(root.gameObject,"Import authored Rangoli");PrefabUtility.UnpackPrefabInstance(root.gameObject,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);root.SetPositionAndRotation(Vector3.zero,old.rotation);root.localScale=Vector3.one*2;var floor=GameObjectUtility.FindUnder(root,"Plane");var fb=GameObjectUtility.BoundsOf(floor);root.position+=new Vector3(-30.4496f-fb.center.x,.0507f-fb.max.y,35.9742f-fb.center.z);root.SetParent(old.parent,true);
 foreach(var mf in root.GetComponentsInChildren<MeshFilter>(true)){var row=data["objects"].First(x=>(string)x["name"]==mf.name);mf.GetComponent<MeshRenderer>().sharedMaterials=row["materials"].Select(id=>imported[(string)id]).ToArray();}
 foreach(var p in oldPieces)p.gameObject.SetActive(false);foreach(var d in oldDecor)if(d)d.gameObject.SetActive(false);if(oldSun)oldSun.gameObject.SetActive(false);foreach(var z in oldZones)z.gameObject.SetActive(false);old.name="Rangoli superseded arrangement";old.gameObject.SetActive(false);
 foreach(var n in new[]{"Rangoli display dais","Rangoli piece rack pedestal","Rangoli human scale display","Shallow floor motifs"}){var t=GameObjectUtility.FindExact(n);if(t)t.gameObject.SetActive(false);}
 root.name="Rangoli - Approved Warm Palette";var board=GameObjectUtility.FindUnder(root,"Cube.005");string[] pieces={"Plane.001","Sphere.001","Cube.004","Cube.003","Star.002"};string[] ids={"Sun","Petal","Diamond","Border","Star"};g.pieces=new GrabbableItem[5];g.sockets=new SnapZone[5];for(int i=0;i<5;i++){g.pieces[i]=DiwaliGameplay.Editor.CoreVenueInstallers.CenterGrab(GameObjectUtility.FindUnder(root,pieces[i]),ids[i],root);g.sockets[i]=GameObjectUtility.MakeZone(g.transform,ids[i],board.TransformPoint(localPoints[i]),.45f);g.sockets[i].transform.rotation=board.rotation*localRotations[i];}
 string[] names={"Plane.002","Cube.006","Cube.007","Cube.008","Cube.009","Cube.010","Cube.011","Cube.012","Cube.013","Sphere.002","Sphere.019","Sphere.027","Sphere.037","Star.001","Star.003","Star.004","Star.005"};g.decorations=names.Select(n=>GameObjectUtility.FindUnder(root,n)).ToArray();g.decorationGroups=new[]{0,3,3,3,3,2,2,2,2,1,1,1,1,4,4,4,4};g.motifs=g.decorations.SelectMany(t=>t.GetComponentsInChildren<Renderer>(true)).ToArray();
 var art=g.decorations[0];var mesh=art.GetComponent<MeshFilter>();var vs=mesh.sharedMesh.vertices;var tr=mesh.sharedMesh.triangles;float best=0;Vector3 axis=Vector3.up;for(int i=0;i<tr.Length;i+=3){var a=art.TransformPoint(vs[tr[i]]);var b=art.TransformPoint(vs[tr[i+1]]);var c=art.TransformPoint(vs[tr[i+2]]);var cross=Vector3.Cross(b-a,c-a);if(cross.sqrMagnitude>best){best=cross.sqrMagnitude;axis=cross.normalized;}}
 var pivot=new GameObject("Authored upright sun rotation pivot").transform;pivot.SetParent(root,true);pivot.position=GameObjectUtility.BoundsOf(art).center;art.SetParent(pivot,true);g.sun=pivot;g.sunRotationAxis=axis;g.preserveAuthoredLayout=true;g.pavilionFloor=floor;var pav=GameObjectUtility.FindUnder(root,"Cube.002");g.pavilionSurface=pav.gameObject.AddComponent<MeshCollider>();((MeshCollider)g.pavilionSurface).sharedMesh=pav.GetComponent<MeshFilter>().sharedMesh;foreach(var n in new[]{"Plane","Cube","Cube.001","Cube.005"}){var t=GameObjectUtility.FindUnder(root,n);var col=t.gameObject.AddComponent<MeshCollider>();col.sharedMesh=t.GetComponent<MeshFilter>().sharedMesh;t.gameObject.isStatic=true;}
 var light=new GameObject("Rangoli authored display warm fill").AddComponent<Light>();light.transform.SetParent(root,true);light.transform.position=GameObjectUtility.BoundsOf(g.decorations[0]).center+Vector3.up*1.5f;light.type=LightType.Point;light.range=6;light.intensity=3;light.color=new Color(1,.78f,.48f);g.displayLight=light;
 EditorUtility.SetDirty(g);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(g.gameObject.scene);Debug.Log("Imported user's raised floor, motif arrangement and upright sun; temporary dais disabled. Sun axis="+axis);
 }
